<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\HasMany;
class Supplier extends Model { use SoftDeletes; protected $fillable=['name','code','phone','email','address','tax_number','notes','status']; public function contacts(): HasMany{return $this->hasMany(SupplierContact::class);} public function purchaseOrders(): HasMany{return $this->hasMany(PurchaseOrder::class);} public function goodsReceipts(): HasMany{return $this->hasMany(GoodsReceipt::class);} public function invoices(): HasMany{return $this->hasMany(SupplierInvoice::class);} public function payments(): HasMany{return $this->hasMany(SupplierPayment::class);} public function returns(): HasMany{return $this->hasMany(PurchaseReturn::class);} }
